package main;

import constants.Constants;
import constants.Message;
import controller.ExpenseController;
import dto.ExpenseRequestDTO;
import java.io.IOException;
import java.util.Scanner;
import utils.FileUtils;
import utils.Validation;

/**
 * Diem bat dau: doc tep du lieu (checklist 1.1: doc tep o Main), menu, ban phim (Scanner chi
 * o day), kiem tung o qua Validation, goi Controller dung 1 lan cho moi lua chon.
 *
 * @author CuongThai Academy
 */
public final class Main {

    // Constructor private: Main chi co ham static (checklist 3.4)
    private Main() {
    }

    // Chay chuong trinh: doc tep, lap menu den khi chon 4
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        ExpenseController expenseController = new ExpenseController();
        boolean isRunning = true;
        int choice = 0;

        // Mo chuong trinh: doc tep roi dua cac dong cho Controller nap vao kho
        expenseController.loadExpenses(readExpenseFile());

        // Hien lai menu sau moi chuc nang, den khi chon thoat (khong dung System.exit)
        while (isRunning) {
            System.out.println(Message.MENU);
            choice = promptChoice(scanner);

            // Loi ghi tep (tu kho) in o catch
            try {
                // Moi lua chon goi controller dung 1 lan
                switch (choice) {
                    // 1: nhap tung o (sai o nao hoi lai o do) roi them chi tieu
                    case Constants.MENU_ADD:
                        System.out.println(Message.TITLE_ADD);
                        expenseController.addExpense(inputExpense(scanner));
                        break;

                    // 2: in bang chi tieu + tong tien
                    case Constants.MENU_DISPLAY:
                        System.out.println(Message.TITLE_DISPLAY);
                        expenseController.displayAll();
                        break;

                    // 3: nhap ID roi xoa
                    case Constants.MENU_DELETE:
                        System.out.println(Message.TITLE_DELETE);
                        expenseController.deleteExpense(inputExpenseId(scanner));
                        break;

                    // 4: chao va tat co de thoat vong lap
                    case Constants.MENU_EXIT:
                        System.out.println(Message.GOODBYE);
                        isRunning = false;
                        break;

                    // Khong xay ra: promptChoice chi tra ve 1 den 4
                    default:
                        break;
                }
            } catch (Exception e) {
                // Cau loi da viet san o Message
                System.out.println(e.getMessage());
            }
        }
    }

    // Doc tep data/expenses.txt thanh phieu chua cac dong; doc loi thi bao va bat dau rong
    private static ExpenseRequestDTO readExpenseFile() {
        ExpenseRequestDTO expenseRequestDTO = new ExpenseRequestDTO();

        // Tep chua co (lan chay dau) thi FileUtils tra danh sach rong
        try {
            expenseRequestDTO.setLineList(FileUtils.readLines(Constants.FILE_NAME));
        } catch (IOException e) {
            // Khong doc duoc thi chay tiep voi danh sach rong
            System.out.println(Message.READ_FAIL);
        }

        return expenseRequestDTO;
    }

    // Nhap du 3 o cua 1 chi tieu, gom vao phieu nhap moi
    private static ExpenseRequestDTO inputExpense(Scanner scanner) {
        ExpenseRequestDTO expenseRequestDTO = new ExpenseRequestDTO();

        expenseRequestDTO.setDate(promptDate(scanner));
        expenseRequestDTO.setAmount(promptAmount(scanner));
        expenseRequestDTO.setContent(promptContent(scanner));

        return expenseRequestDTO;
    }

    // Nhap ID can xoa, gom vao phieu nhap moi
    private static ExpenseRequestDTO inputExpenseId(Scanner scanner) {
        ExpenseRequestDTO expenseRequestDTO = new ExpenseRequestDTO();

        expenseRequestDTO.setId(promptId(scanner));

        return expenseRequestDTO;
    }

    // Hoi lua chon menu (1 den 4) den khi hop le
    private static int promptChoice(Scanner scanner) {
        // Lap den khi Validation chap nhan
        while (true) {
            // In cau nhac, doc dong va kiem
            try {
                System.out.print(Message.INPUT_CHOICE);
                return Validation.getChoice(scanner.nextLine(), Constants.MENU_ADD,
                        Constants.MENU_EXIT);
            } catch (Exception e) {
                // Sai thi in cau bao loi roi hoi lai
                System.out.println(e.getMessage());
            }
        }
    }

    // Hoi ngay den khi dung dang dd-MMM-yyyy va co that
    private static String promptDate(Scanner scanner) {
        // Lap den khi Validation chap nhan
        while (true) {
            // In cau nhac, doc dong va kiem
            try {
                System.out.print(Message.INPUT_DATE);
                return Validation.getDate(scanner.nextLine());
            } catch (Exception e) {
                // Sai thi in cau bao loi roi hoi lai
                System.out.println(e.getMessage());
            }
        }
    }

    // Hoi so tien den khi la so lon hon 0
    private static double promptAmount(Scanner scanner) {
        // Lap den khi Validation chap nhan
        while (true) {
            // In cau nhac, doc dong va kiem
